import{_ as t,c as s,o as n,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"孔易闡真*雜卦傳","description":"周易闡真 - 孔易闡真*雜卦傳","frontmatter":{"title":"孔易闡真*雜卦傳","description":"周易闡真 - 孔易闡真*雜卦傳"},"headers":[],"relativePath":"classics/chanzhen/066.md","filePath":"classics/chanzhen/066.md"}'),c={name:"classics/chanzhen/066.md"};function o(i,a,l,d,p,h){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"孔易闡真-雜卦傳",tabindex:"-1"},[r("孔易闡真*雜卦傳 "),e("a",{class:"header-anchor",href:"#孔易闡真-雜卦傳","aria-label":"Permalink to “孔易闡真*雜卦傳”"},"​")],-1),e("p",null,"孔易闡真*雜卦傳 ​乾剛，坤柔。 ​乾者，健也。健而又健，剛之至矣。取象為天，物之至剛者莫如天。天之為道，一氣上下，流行不息，亙古如斯。惟其體剛，故能始萬物而易知。人資天之氣而始，即具此剛而易知之德。剛者，正氣也，而命寓焉。修道者，造命之學，即養此剛健之正氣耳。養正氣必如天之易知，不為物屈，而後正氣常存，命寶堅固，與天為徒矣。坤者，順也。順而又順，柔之至矣。取象為地，物之至柔者莫如地。地之為道，至厚至靜，至卑至下，永久不變。惟其體柔，故能生萬物而簡能。人資地之氣而生，即具此柔而簡能之德。柔者，真心也，而性寄焉。修道者，修性之學，即修此柔順之真心耳。修真心必如地之簡能，無物不載，而後心地虛靜，真性不昧，與地為配矣。蓋在天為易知者，在人為良知；在地為簡能者，在人為良能。能剛則良知而易，不思而得；能柔則良能而簡，不勉而中。良知良能，剛柔相合，健順之德全，性命之事了。故古人謂金丹之道，至簡至易之道也。比樂，師憂。 ​比者，親比，以陰比陽也。五陰而比一陽，陰不陷陽而順陽，順以御險，致樂之道也。人之不能有樂者，以其陷真而順假也。若能順真以化假，則假亦歸真，何不樂乎?師者，兵道，以正制邪也。一陽而帥五陰，陽不為陰所陷而統陰，險中行順，備憂之道也。人之所以有憂者，以其能處順，而不能處逆也。若能以順而處逆，則逆亦是順，有何憂乎?比以陰而順陽，順陽即不陷陽；師處逆而行順，行順而陽不陷。陷與不陷，是在順與不順耳。一順而致樂備憂，無往不利矣。臨、觀之義，或與或求。 ​臨者，親近也。順中有悅，悅在於順，將欲取之，必先與之，不與而與，或與之也。觀者，覺察也。順時漸行，漸以行順，順其所欲，漸次導之，不求而求，或求之也。與必順其悅，求必順而巽，與之求之，總是一順，所爭者內順外順耳。外順可以臨物，取彼之歡心，借假而修真。內順可以觀己，增我之道德，由真而化假。以臨而與，以觀而求，彼悅而我即悅，先與後求，此順道之所以為貴歟！屯見而不失其居，蒙雜而著。 ​屯者，迍邅難前也。一陽動於險中，道心發現之時。道心發現，內有主宰，不行險而防險，雖動而不失其居。特以一陽動於坎地，陽氣初復，陰氣正盛，未可妄動，不失其居，正欲待時以出險耳。蒙者，昏昧不明也。一陽陷於陰中，人心已生之時。人心已生，是非相混，不順陽而陷陽，故雜而昏昧著外。然雖陽氣陷於坎中，陽氣未泯，陰氣方著，正可隨時止險耳。陽動險中，待時而進陽；陰陷其陽，隨時而退陰。進陽退陰，各有其時，動之止之，不失其時，可以動而出險，止而濟險，陽氣不為陰氣所傷矣。震，起也；艮，止也。 ​震者，一陽進於二陰之下，陽氣順時而起也，取象為雷。雷聲之起，奮發而莫可遏止。雷外有雷，以此雷而及彼雷，千雷萬雷，總在一起。修道者振發志氣，一往直前，由近達遠，亦必如雷之動，方為剛於起，而不為人慾所牽矣。艮者，一陽居於二陰之上，陽氣順時而止也，取象為山。山體之止，靜定而永不遷移。山外有山，以此山而連彼山，千山萬山，總是一止。修道者斂藏神氣，不動不搖，由內達外，亦必如山之止，方是剛於止，而不為境遇所移矣。用剛，則震起而果決動直；養剛，則艮止而穩定靜專。起之止之，能隨其時，無往不可用剛，無處能傷其剛矣。損、益，盛衰之始也。 ​損者，減少也。悅於止而止其悅，止其不正之悅，而止於其所，損其柔之有餘也。益者，增多也。動之巽而巽其動，進其不能之動而漸於能動，益其剛之不足也。損其柔之有餘，柔而不至於過盛；益其剛之不足，剛而不至於有衰。然損之益之者，欲其剛柔俱歸中正也。若損益太過，有餘者損而必至於太衰，不足者益而必至於過盛，是損益又為盛衰之始也。故修道者，用增減之功，必以剛柔中正為指歸。剛柔中正，剛中有柔，柔中有剛，剛柔一氣，陰陽和合，金丹凝結矣。大畜，時也；無妄，災也。 ​大畜者，大有養也。剛於止而止其剛，剛不妄用，隨時而用，可剛則剛，可止則止，止於至善而不遷，大畜而能合時者也。無妄者，勇於事也。動之剛而剛於動，動之太猛，任性之剛，不宜剛而剛，不宜動而動，動之固執而不通，無妄而自招災者也。夫剛在內者，嚴以治己，外不足而內有餘，愈畜愈大，浩氣充塞，養之足而行之通，無妄於內，自無妄於外也；剛在外者，躁以應物，外有餘而內不足，有動有妄，乖和失中，涉於假而傷其真，養之不大，必行之不通也。然則，能大畜者，方能無妄；欲無妄者，先須大畜。若畜之不大，而欲行之無妄，雖無妄而實有妄，斯其所取災也。修道者可不善養浩氣，配義與道，以期其至誠無妄乎?萃聚，而升不來也。 ​萃者，聚也。內順而外悅，順則人慾俱死，悅則躁性俱化，人慾無而真陰現，躁性化而真陽還，陰陽相合，正氣凝聚，金丹有象矣。升者，上也。內巽而外順，巽則漸進於道，順則敬謹於行，漸進而不過於剛，敬謹而不過於柔，剛柔相濟，客氣不來，金丹可全矣。但欲正氣凝聚，須要順其悅，先取彼之歡心，彼不悅而他家真實不得，順其所悅，正於殺機中盜生氣耳。欲客氣不來，須要巽而能順，先克己之私心，己不克而我家舊染不去，巽而能順，正在順道中行逆道耳。盜生氣能萃，行逆道能升。能萃能升，真者聚而假者不來。萃至於五行攢簇，行至於至善無惡，有無一致，性命俱了矣。謙輕，而豫怠也。 ​謙者，虛其所有也。止於內而順於外，絕不用剛也。然止剛而用柔，易於謙之太過，自輕而不知自重，有傷於剛，尤必貴乎順中知止，止於其所，謙於外而不輕慢於內也。豫者，樂其所有也。順於內而動於外，順行其剛也。然陰順而陽動，易於豫之太過，懈怠而不知防閒，有傷於柔，尤必貴乎動中用順，順守其正，豫於外而不懈怠於內也。不輕則為真謙，不怠則能長豫。不輕不怠，謙以致豫，豫而能謙，動之止之，無往不順矣。噬嗑，食也；賁，無色也。 ​噬嗑者，口食物而必合也。動而必明，不使有一行違背乎理，如食物口合齒動，動必有時也。賁者，妝飾也。以明運止，不使有一時昏迷其性，如無色妝飾文采，質必以文也。動而不出於明，動而不妄；明而不出於止，明而有養。動必本明，動即明也；止出於明，止亦明也。動止皆明，自明明德，而止於至善，其明無處不在矣。兌見，而巽伏也。 ​見音現。兌者，一陰見於二陽之上，陽以陰濟，剛而不至於過亢，其德和悅，取象為澤。澤之為物，上開下合，滿而不溢，盈而不流，澤外有澤，澤澤相通，浸潤甚多也。修道者，心平氣和，內外如一，有若無，實若虛，不滿不盈，必如澤澤相通，無物不浸，而後謂之和氣外現矣。巽者，一陰伏於二陽之下，陽尊陰卑，柔而不至於太懦，其德善入，取象為風。風之為物，氣剛行緩，不疾而漸達，不猛而深入，風后有風，風風相續，循序前進也。修道者，心堅志遠，循序下功，以誠而入，以柔而用，不即不離，必如風風相續，無處不到，而後能以深造自得矣。柔而現外者，和剛也；柔而伏下者，進剛也。能和其剛，則剛藏於柔，剛而不至於有餘；能進其剛，則柔求其剛，柔而不至於不及。此用柔而不傷其剛，見之伏之，無可無不可矣。隨，無故也；蠱，則飭也。 ​隨者，彼此相隨也。陽動而陰悅，陽隨陰而陰隨陽，陰陽相隨，有故者而即無故。人自先天失散，真性已昧，情慾亂起，已有故矣。今者以震求兌，於殺機中盜生機，情來歸性，仍是無故之物，本來面目也。蠱者，事有敗壞也。陰進而陽止，陰傷陽而陽止陰，陰為陽制，有蠱者飭即不蠱。人自後天用事，客氣來入，主氣有虧，是有蠱矣。今者以剛制柔，於後天中返先天，明善復初，仍是不蠱之物，天良本性也。無故用隨，陽求陰也。有蠱則傷陰，順陽也。陽求陰，借陰可以復陽；陰順陽，借陽可以化陰。復陽化陰，隨蠱之道盡矣。剝，爛也；復，反也。 ​剝者，消去也。五陰而剝消一陽，如人順乎後天之陰。剝陽將盡，勢必剝之不已，而壞爛肢體也。復者，回反也。一陽回反於五陰之下，如人逆回先天之陽，生機又見，漸可復陽於純，而重現本面也。然剝者，即復之兆；反者，即不爛之幾。能於方剝之時，順而止之，不使剝陽於盡，藉此剝餘之微陽，別立乾坤，重安鼎爐，隨其時而復之，則已失者可得，已去者能還，先天純而後天化，更何有剝爛之患乎?晉，晝也；明夷，誅也。 ​晉者，明進也。由順生明，明在暗出，如晝而出地之日，漸進而上，愈上愈明，光輝增升也。明夷者，明傷也。因順敗明，明入於暗，如夜而入地之日，漸退而下，愈下愈晦，光輝誅傷也。一自暗而出明，一自明而入暗，所爭者順內順外耳。順在內，則妄念不生而心誠，誠則能明矣；順在外，則物慾所蔽而神昏，昏則失明矣。內順者，逆道也；外順者，順道也。逆則生明，而明通；順則誅明，而明晦。順逆之間，明之得失系之。修道者，可不知其順中用逆之道乎?井通，而困相遇也。 ​井者，養人之道，言其時通也。通所以達其道，然未巽化於人，先須巽化於己。己無險，而方可濟人之險。蓋養己不到，是險中之巽；養己已到，是巽以出險。出險而巽，養己畢而又養人，其所養不窮也。困者，艱難之境，言其相遇也。困所以驗其德，但未能以濟險，先貴能以處險，處險能悅，而濟險遂悅。蓋遇困不受，是悅行於險；遇困能受，是處險能悅。身可困而心不可困，雖遇困而亦亨矣。遇通養人，遇困養己。通時能養人者，困時必能養己；困時能養己者，通時即能養人。通困相遇，時有變而養亦有變。順之逆之，俱皆有養，方謂修道之士也。鹹，速也；恆，久也。 ​鹹者，無心之感也。內止而外悅，悅本於止，止以求悅，止而能養，悅而能行，悅止相需，寂然不動，感而遂通，以神交而不以形交，陰陽隔礙潛通，言其速也。恆者，有心之恆也。內巽而外動，巽以運動，動必以巽，巽而不懦，動而不猛，巽動合一，心堅志遠，不急不緩，自有為而入無為，功力由漸而頓，言其久也。夫所謂無心者，無人心也；有心者，有道心也。無人心而陰陽感之速，有道心而功力行之久。感速則出於自然，無修無為；恆久則出於勉強，有作有為。有為無為，各有妙訣，總在無人心、有道心分之。若到大道完成之後，有無俱不立，物我悉歸空，入於至誠如神之地，不但人心用不著，即道心亦用不著矣。渙，離也；節，止也。 ​渙者，陽氣陷下，陰氣進上，陰陽彼此分離也。節者，險事在外，悅事在內，境遇有困能止也。但陰陽分離，亦有致合之道，是在於陷陽之處，巽緩以漸濟之耳。有困能止，即有致通之機，是在於險事之中，和順以正處之耳。漸以濟渙，始離終合，正以立節，有險亦通。然渙者，皆由不知有節之故。若能知節，非禮不履，非道不處，非義不行，境遇在彼，造命在我，何渙之有?故卦德渙之險在內，節之險在外也。解，緩也；蹇，難也。 ​解者，陽氣出險而緩也。陽氣出險，坎中一陽震動，正陰氣退散、陽氣難緩之時。陽氣難緩，己不為陰氣所傷，可以點化群陰矣。蹇者，陽氣在險有難也。陽氣在險，坎中一陽尚藏，正陰氣旺盛、陽氣困難之時。陽氣困難，非可急求出險，須當靜養微陽矣。解之點化群陰者，以其陽氣雖出險，陰氣猶未消，禍根尚在，即能一時得緩，不久又為陰陷，解而又不解，尤必貴乎出險之動，用增減之功，借陽以退陰。陰氣退盡，陽氣復全，方是真解蹇。必靜養微陽者，以其陽氣在於坎，陰氣障其陽，若強脫險，不但不能脫險，而且有以致險，不蹇而亦蹇。是必貴乎險中之止，用防閒之道，借陰以保陽，陽氣不失，陰氣漸退，方能無蹇。陽出險，而當進陽退陰；陽在險，而當養陽防陰。退陰防陰，各有火候，隨時而用，方不誤事也。睽，外也；家人，內也。 ​睽者，彼此相隔也。火在上而金在下，金火不投，神馳於外，情動於內，因假失真，言其用明於外也。家人者，彼此合一也。木在上而火在下，火中生木，元神守內，柔性應外，以虛求實，言其用明於內也。用明於外，火不返本，妄情動而真情昧；用明於內，火已歸根，假化成真，氣性消而真性現。明之一內一外，睽與不睽，一家不一家分之。修道者，可不迴光返照，以養其明乎!否、泰反其類也。 ​否者，塞室也。剛氣用外，柔性藏內，正氣散而邪氣聚，滿腔私慾，塞閉靈竅，柔傷於剛，否之由也。泰者，通達也。剛氣在內，柔性在外，嚴以治己，寬以應物，其心日小，其德日大，剛以柔用，泰之兆也。外剛內柔則否，外柔內剛則泰，總是一剛一柔。所爭者，剛柔內外，反其類而否泰分之。剛柔之用，豈可忽焉乎!大壯則止，遁則退也。 ​大壯者，剛之太過也。剛於內而動於外，已剛而又進剛。剛而妄動，動必傷剛，壯之大矣。則止者，可止即止，止以養壯，不使剛進太過也。遁者，剛之收斂也。止其剛而剛於止，已剛而即止剛，剛而止所，不敗其剛，遁得其時矣。則退者，可退即退，退以避咎，不使陰氣潛生也。蓋用剛之道，未剛須進剛，已則須養剛。進剛者用壯也，養剛者藏壯也。當動則動，動而進壯，當止則止，止而藏壯，以時而行，不失其正。動固壯，止亦壯，遁固養，壯亦養，無往而不可剛，無往而有傷剛矣。噫!明進退，知止足，豈愚昧而能為？識急緩，慮吉凶，須匠手以斟酌。大有，眾也；同人，親也。 ​大有者，有之眾也。健於內而明於外，實腹之後而能虛心。能虛其心，則元神守室，以火鍊金，金遇火而還原生明，大藥成就，萬理畢集，信步走去，頭頭是道。以明成健，大有而愈有，其所有者甚眾也。同人者，與人親也。明於內而健於外，虛心之後而又實腹。能實其腹，則正氣常存，以金養火，火遇金而返本不燥，陰陽相和，內外合道，寂然不動，感而遂通。以健濟明，同人而人同其所同者，最親也。健而明以火鍊金，明而健借金返火。金還火返，金火同宮，金即是火，火即是金，健明如一，有即能同，同而愈有，是謂大有，是謂大同。大有、大同，有陰有陽，有虛有實，有人有我，大小無傷，剛柔兩全，渾然天理，一氣流行，性命雙修之道畢矣。革，去故也；鼎，取新也。 ​革者，去其故而不用也，去故之道。金在上，火在下，以火鍊金，去其金之濁氣，而返於陽耳。人之妄情為陰金，人之真情為陽金，以元神之真火，煅去妄情之陰金，妄情去而真情現，是謂無情之情，永為不壞之金，所謂“火鍊金明”者，是也。鼎者，煅其物而取新也，取新之道。火在上，木在下，火中成木，化其木之濁質，而歸於真耳。人之氣性為陰木，人之真性為陽木，以元神之真火，煅去氣性之陰木，氣性化而真性現，是謂無性之性，永為無煙無焰之木，所謂“火中生木”者，是也。革故鼎新，假者去而真者來，金木文並，性情相合，還元返本矣。然必先革故者，先煉己，虛心以待時也。後鼎新者，後採藥，實腹以結丹也。可知未虛心而不能實腹，而又當虛心。明之一內一外，性情皆化為真，有為無為，一以貫之也。小過，過也；中孚，信也。 ​小過者，小者過也。止以運動，動必本止，外虛內實，實藏於虛，小者過而大者不過；可止則止，可動則動，動不離止，止於至善無惡之地矣。中孚者，中有信也。悅而漸行，漸以通悅，外實內虛，以虛求實，信於中而行於外；以誠而入，以柔而用，漸進於深造自得之地矣。然不能自小者，亦不能信於中；不能中信者，亦不能小之過。小過、中孚，虛而實，實而虛，虛實並用，動止相需，悅巽如一，過而不過，信在其中，何患修道不成乎!豐，多故也；親寡，旅也。 ​疑是旅寡親，今作旅寡親解。豐者，盛大也。既明且動，動以行明，明動相資，明之足而行之大，豐之極矣。豐極易於自滿，自盈不能防閒。明過傷其明，動過敗其行，故多故也。多故，則事有反覆，行必顛沛矣。旅者，一過而不久留也。即止且明，明本於止，明止相需，止而有養，明而不傷，萬事一旅也。旅事即能素位而行，不願乎外，止於內而不止於外，明於己而不明於人，故寡親也。寡親，則物來順應，事不過留矣。是在保豐者，豐其明而又貴旅明，明不妄動；行旅者，旅其明而又貴豐明，明不太止。豐以旅為用，旅以豐為體，或動而用明，或止而養明，動止皆得其正，可以不傷其明矣。離上，而坎下也。 ​離者，一陰麗於二陽之中，外實內虛，體剛而用柔，其象為火。火性焰上，故離上也。坎者，一陽陷於二陰之中，外虛內實，體柔而用剛，其象為水。水性流下，故坎下也。人之躁性如火，一有觸犯，爭勝好強，予聖自雄，肆無忌憚，亦火之焰上也。人之慾心如水，妄念百端，棄真入假，逐風揚波，入於下流，亦水之流下也。聖人教人懲忿者，即懲此躁火耳；教人窒慾者，即窒此欲心耳。躁心懲而火返本，則心虛而生明，元神不昧；欲心窒而水歸源，則腹實而無險，元精不漏。神明精粹，真水真火，彼此相濟，陰陽相合，先天之氣，自虛無中來矣。小畜，寡也；履，不處也。 ​小畜者，言其畜之寡也。柔巽畜健，雖剛亦柔，其畜不大，其行不遠。履者，言其不下處也。悅於履健，雖柔亦剛，其志能專，其行自力。蓋小畜之健在內，真陽未傷，為上德之人。可以有為者，乃以小而畜，浩氣不振，甘居卑下，自暴自棄，坐觀成敗，必至陽極而陰潛生，吉中而兇，暗藏剛為柔鈐，有能者歸無能矣。履之健在外，真陽已虧，為下德之人。系無能為者，乃能悅於履健，以己求人，從容進步，久於其道，不即不離，必至自近而可達遠，自卑而漸登高，柔得剛濟，無能者亦有能矣。然則修真之道，不論人之才德高低，只論其有志無志耳。無志，雖才人智士，皆所不能；有志，雖愚夫愚婦，俱能為之。所謂“悟之者立躋聖位，迷之者萬劫沉流”也。需，不進也；訟，不親也。 ​需者，待時也。健在險中，遇險能健，險之在彼，健之在我，欲取於人，不失其己，故需而不進。不進待時，特欲取真陽出坎耳。訟者，爭勝也。險在健中，因健有險，內而陰毒，外而兇暴，不但損人，而且傷己，故訟而不親。不親好強，終必自陷真陽於坎矣。不進健而健無傷，反借險以養健；不親人而人不親，反用健以招險。同一健也，同一險也，健於內有險可以無險，健於外無險亦自致險，一內一外，禍福隨之。修道者，可不潛養天德，以防其險乎!大過，顛也；頤，養正也。 ​大過以下卦不反對，先儒以為錯簡，今暫以反對序。大過者，陽太過也。巽於內而悅於外，陽極而陰即入，陰一入而人心起，見景生情，順其所欲，性亂命搖，故曰顛也。頤者，取其養也。動於內而止於外，陰極而陽復回，陽一回而道心發，內有主宰，遷善改過，止於其所，故曰養正也。修真之道，始終養正之道也。實腹而能虛心，虛以養實，正而可以不顛；虛心而能實腹，實以濟虛，顛而可歸於正。故大過之象，內實外虛，示其實必求虛也；頤之象，外實內應，示其虛必求實也。或先實腹而後虛心，或先虛心而後實腹，虛實兩用，有為無為之道盡，養正之功畢矣。漸，女歸待男行也；歸妹，女之終也。 ​漸者，徐緩之義。修道貴乎徐緩，徐緩則止於其所，從容不迫，循序漸進，煉己待時。如卦象少男而配長女，女待男行而後歸，此陰陽交合之正，夫婦之真，久則成事，情性如一，陰陽混合也。歸妹者，急速之義。修道忌其急速，急速則妄猜私議，不窮實理，任性造作，躐等而求。如卦象少女而求長男，女非其時而苟合，此陰陽交合不正，夫婦之假，久則敗事，以女而終，獨守孤陰也。修真之道，窮理盡性至命之學也。有火候，有工程，必須用漸修之功，方能深造自得。若急欲成功，冒然下手，其進銳者，其退速，安能追二氣於黃道，會三性於元官乎?欲成大道，舍漸修之功，餘無他術矣。既濟，定也；未濟，男之窮也。 ​既濟者，陰陽已濟也。水上火下，水火烹煎，水得火而不寒，火得水而不燥，水火來往，乾坤為體，坎離為用，良知良能，健順如一，精神相戀，陰陽混成，故曰定也。定則陰陽俱歸黃道，一氣流行，生機常存而不息矣。未濟者，陰陽相離也。火上水下，火水異處，水下流而火上炎，水不能制火，火不能煎水，良知變為假知，躁性發矣，良能變為假能，欲心生矣。躁性即火，欲心即水，燥性用外，欲心藏內，性亂命搖，陰陽不濟，故曰男之窮也。男窮則陽為陰陷，假者用事，真者埋沒，而不彰矣。但既濟之道，乃陰陽濟極之時。濟極將不濟，須用無為之道以保濟。保濟之功，用天然真火，煅去後天一切滓質，陰氣化而陽氣純，大丹成熟，脫胎神化，入於不生不滅之境矣。未濟之道，乃陰陽未濟之時。未濟須求濟，當用有為之功以致濟。蓋坎中所陷真陽，原是乾宮之物；離中所藏之陰，原是坤宮之物。今者於坎宮欲水之中，取出一點真一之陽水，撲滅離宮之燥火；於離宮燥火之中，取出一點虛靈之真火，煅盡坎宮之慾水。取坎填離，以離歸坎，真陰真陽，彼此和合，真水真火，兩不相離，未濟而至於濟，仍是乾健坤順本面，良知良能原物矣。但保濟致濟，有為無為，其道不同，下手各別。故既濟之義，以明御險也；未濟之義，險中出明也。以明御險，防險養明，先天中返後天，所以保濟也。險中出明，以明破險，後天中返先天，所以致濟也。保濟致濟之訣，莫過於此。噫!順則生人生物，逆則為聖為賢。逆之一字，豈易知乎!姤，遇也，柔遇剛也；夬，決也，剛決柔也。 ​姤者，遇也。以一柔而遇五剛，陽極而陰潛生，不期遇而忽遇，陰氣乘間而入也。夬者，決也。以五剛而決一柔，陽將純而陰將盡，不強決而自決，陽氣隨時而進也。人自有生以後，一點先天陽氣，藏於幻身之中，日生夜長，年至二八，先天氣足，名曰純陽之體，為上德之人。當此之時，若遇明師指點，行無為自然之道，以成後天之功，性了而命亦全，便為無漏真人矣。否則，陽極必陰，一陰潛生於純陽之下，陰姤其陽，後天用事，陰日長，陽日消，不至消滅其陽而不止。一陰雖微，為禍最烈。金丹有為之道，正為中下之人姤後而設。有為者，進陽決陰也。以陽決陰，必先於陰中進陽，進陽正為退陰計耳。陽氣進於九五中正之位，是正位凝命，陽氣已足，陰氣已弱，縱橫逆順，道心用事，金丹有象，於此點化群陰，如貓捕鼠。但一切群陰皆化，僅有一點陰氣之根未消，猶足為道累。聖胎雖結，不能脫化。古真雲“一毫陰氣不盡不仙”，正言此群陰之根也。群陰之根為何根?即人心識神是也。識神者，歷劫輪迴之種子，生生死死之根蒂，其權最大，其根最深，在姤為初生之一陰，在夬為決終之一陰。姤時他先發，夬時他後去，生人者是他，死人者是他，人多貪戀，不肯果決除去，即欲去之，亦不易於去。去之之道，健而能和，剛以柔用，不即不離，勿忘勿助，待其黨類已盡，勢孤力單，一決即去，拔去歷劫禍根，現出父母未生以前本相，圓陀陀、光灼灼、淨倮倮、赤灑灑，不生不滅，為金剛不壞之物矣。君子道長，小人道憂也。 ​易之道，一陽一陰之道也。陰為柔，陽為剛。剛之德主健，柔之德主順。健則易知，順則簡能。易知即人之良知，簡能即人之良能。良知本於天，屬命；良能本於地，屬性。人秉天地易簡之德，知能俱良，剛柔兼該，性命寓於一身矣。及交後天，良知變為假知，良能變為假能，陰陽不調，剛柔不當，性亂命搖，失其秉受天地簡易知能之良。孟子所謂“人之所以異於禽獸者幾希，庶民去之，君子存之”。存此良知良能，則為君子；失此良知良能，則為庶人。君子道長，君子存之也。小人道憂，庶民去之也。蓋君子之道，復此良知良能，而退假知假能，故長；小人之道，順其假知假能，而棄良知良能，故憂。良知良能屬於先天，假知假能屬於後天。復其先天之真，則了性了命，入於生路，道之長也；順其後天之假，則昧性傷命，入於死路，道之憂也。六十四卦，以乾坤為門戶者，示人以剛柔簡易之道也；其餘六十二卦者，示人以變化簡易之道也。六十四卦，三百八十四爻，無非教人知其不簡易，而變之化之，期歸於簡易耳。變化簡易，知能俱良，而為君子；不變化簡易，則知能不良，而為小人。君子小人，只在知變化不知變化上分別耳。金丹之道，君子之道。君子之道，即逆運陰陽之道也。所謂金丹者，即簡易良知良能混成之性。所謂還丹者，即還此簡易良知良能之本面。所謂金液大丹者，即煅煉此簡易良知良能混成之性，永久不壞也。所謂火候者，即六十四卦變化簡易知能，俱歸於良之道也。所謂藥物者，即剛柔簡易知能俱良之德也。所謂聖胎者，即剛柔簡易知能俱歸於良也。所謂脫胎者，即剛柔混成、簡易不拘、知能入神、有無不立也。丹經子書千帙萬卷，總不外易理。易理六十四卦，三百八十四爻，總不出此剛柔簡易知能俱良之道。易為君子謀，不為小人謀，特以君子能修此剛柔簡易之道，逆運陰陽，復還本來良知良能之原物也。一切凡夫小人，認假為真，順其後天陰陽，適以昧其天根，自取滅亡已耳，焉知修此先天道運大道乎!",-1)])])}const f=t(c,[["render",o]]);export{_ as __pageData,f as default};
